tool_calls:
awk -F= '
FNR==NR { if ($0 ~ /^[[:space:]]*(#|$)/) next; k=$1; sub(/^[^=]*=/,""); a[k]=$0; next }
{ if ($0 ~ /^[[:space:]]*(#|$)/) next; k=$1; sub(/^[^=]*=/,""); b[k]=$0; order[++n]=k }
END {
  print "Config diff: /data/v1.conf -> /data/v2.conf"; print ""
  print "Added keys:"; c=0
  for (i=1;i<=n;i++){k=order[i]; if(!(k in a)){printf "  + %s = %s\n",k,b[k]; c++}} if(!c)print "  (none)"
  print ""; print "Removed keys:"; c=0
  for (k in a) if(!(k in b)){printf "  - %s = %s\n",k,a[k]; c++} if(!c)print "  (none)"
  print ""; print "Changed values:"; c=0
  for (i=1;i<=n;i++){k=order[i]; if((k in a)&&a[k]!=b[k]){printf "  ~ %s: %s -> %s\n",k,a[k],b[k]; c++}} if(!c)print "  (none)"
}' /data/v1.conf /data/v2.conf

